-- ── SCM_ADM_CMBO_SQL_M 11행 MERGE (ON = PK 실측 ['SQL_ID', 'MDU_DIVS_CD']) [SQL_ID] ──
MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T USING (SELECT 'Division' AS SQL_ID, 'ALL' AS MDU_DIVS_CD, 'Division 조회' AS SQL_NM, 'SELECT 	DIVISION_ID AS CODE 	  , DIVISION_ID AS NAME FROM 	SCM_MST_DIVISION WHERE  (@divisionId IS NULL OR DIVISION_ID LIKE ''%'' || @divisionId || ''%'') 	OR (@divisionId IS NULL OR DIVISION_NAME LIKE ''%'' || @divisionId || ''%'') GROUP BY DIVISION_ID ORDER BY DIVISION_ID      ' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'SYSTEM' AS CREATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'admin' AS LAST_UPDATED_BY, TO_DATE('2026-08-11 11:35:53','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) S ON (T.SQL_ID=S.SQL_ID AND T.MDU_DIVS_CD=S.MDU_DIVS_CD)
WHEN MATCHED THEN UPDATE SET T.SQL_NM=S.SQL_NM, T.SQL_DTL_CTN=S.SQL_DTL_CTN, T.USE_YN=S.USE_YN, T.LAST_UPDATED_BY=S.LAST_UPDATED_BY, T.LAST_UPDATE_DATE=S.LAST_UPDATE_DATE
