MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T USING (SELECT 'EndCustomerByDivisionDept' AS SQL_ID, 'DM' AS MDU_DIVS_CD, 'End Customer by division, team' AS SQL_NM, 'SELECT DISTINCT 	A.DIVISION_ID AS DIVISION_ID,     A.END_CUSTOMER AS CODE,     NVL(D.SEGMENT3, A.END_CUSTOMER) AS NAME FROM ( 	SELECT DISTINCT 	     site.DIVISION_ID 	   , site.END_CUSTOMER 	   , item.DEPT_ID, item.PROJECT_CODE 	   , site.SCM_SITE_ID AS CODE 	   , site.SCM_SITE_ID AS NAME 	FROM      SCM_MST_SITE site 	LEFT JOIN SCM_MST_SITE_ITEM item 	       ON site.DIVISION_ID = item.DIVISION_ID 	      AND site.SCM_SITE_ID = item.SCM_SITE_ID ) A LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D     ON A.DIVISION_ID = D.SEGMENT1    AND A.END_CUSTOMER = D.SEGMENT2    AND D.LOOKUP_TYPE = ''END_CUSTOMER''    AND D.VALID_YN = ''Y'' WHERE 1 = 1 --  AND ( --        (@divisionId = NULL OR @divisionId = ''ALL'' OR @divisionId = '''') --        OR A.DIVISION_ID IN ( --            SELECT REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) --            FROM DUAL --            CONNECT BY REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) IS NOT NULL --        ) --      ) --  AND ( --        (@deptId = NULL OR @deptId = ''ALL'' OR @deptId = '''') --        OR A.DEPT_ID IN ( --            SELECT REGEXP_SUBSTR(@deptId, ''[^,]+'', 1, LEVEL) --            FROM DUAL --            CONNECT BY REGEXP_SUBSTR(@deptId, ''[^,]+'', 1, LEVEL) IS NOT NULL --        ) --      ) --  AND A.DIVISION_ID IN ( --        SELECT DISTINCT UNIT_ID --        FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M --        WHERE USER_ID = @sesUserId --          AND UNIT_TP_CD = ''D'' --      )   AND A.DIVISION_ID IS NOT NULL   AND A.DEPT_ID IS NOT NULL   AND A.END_CUSTOMER IS NOT NULL ORDER BY A.END_CUSTOMER' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'SYSTEM' AS CREATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'SYSTEM' AS LAST_UPDATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) S ON (T.SQL_ID=S.SQL_ID AND T.MDU_DIVS_CD=S.MDU_DIVS_CD)
WHEN MATCHED THEN UPDATE SET T.SQL_NM=S.SQL_NM, T.SQL_DTL_CTN=S.SQL_DTL_CTN, T.USE_YN=S.USE_YN, T.LAST_UPDATED_BY=S.LAST_UPDATED_BY, T.LAST_UPDATE_DATE=S.LAST_UPDATE_DATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE) VALUES (S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, S.CREATED_BY, S.CREATION_DATE, S.LAST_UPDATED_BY, S.LAST_UPDATE_DATE);
