WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE) VALUES (S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, S.CREATED_BY, S.CREATION_DATE, S.LAST_UPDATED_BY, S.LAST_UPDATE_DATE);
MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T USING (SELECT 'Measure' AS SQL_ID, 'DM' AS MDU_DIVS_CD, '[C] AS-IS @Code=''Measure'' 수작업 통합 변환 — @Param1→@mnuId + SHEET_NAME=@Param2 제거·' AS SQL_NM, 'SELECT DISTINCT A.COLUMN_NAME AS CODE, CASE WHEN A.COLUMN_NAME = ''CUST_FCST_EDI_ORG'' THEN '' └ '' || ''EDI[Org.]'' WHEN A.COLUMN_NAME = ''CUST_FCST_EDI'' THEN '' └ '' || ''EDI'' ELSE A.COLUMN_LABEL_NAME END AS NAME FROM SCM_MGR.SCM_MST_SHEET_MEASURE A WHERE A.PROGRAM_ID = @mnuId AND A.VALID_YN = ''Y'' UNION ALL SELECT MEASURE AS CODE, '' └ '' || MEASURE AS NAME FROM SCM_MGR.DM_MST_CUSTOMER_FCST WHERE VALID_YN = ''Y'' AND MEASURE IS NOT NULL AND MEASURE_GROUP = ''CUST_FCST'' AND @mnuId IN (''DMF0003'', ''DMF0035'', ''DMF0003_TEST'', ''DMF0082'') GROUP BY MEASURE UNION ALL SELECT ''Immidiate'', ''    └ '' || ''Immidiate'' FROM DUAL UNION ALL SELECT ''Planning_Forecast'', ''    └ '' || ''Planning_Forecast'' FROM DUAL UNION ALL SELECT ''Commercial_Agreement'', ''    └ '' || ''Commercial_Agreement'' FROM DUAL UNION ALL SELECT ''Firm_Temp'', ''    └ '' || ''Firm_Temp'' FROM DUAL UNION ALL SELECT ''Manumacturing_Material_Temp'', ''    └ '' || ''Manumacturing_Material_Temp'' FROM DUAL UNION ALL SELECT ''Material_Temp'', ''    └ '' || ''Material_Temp'' FROM DUAL UNION ALL SELECT ''Backorder'', ''    └ '' || ''Backorder'' FROM DUAL UNION ALL SELECT ''Cust.FCST_EXCEL[P+P]'', '' └ '' || ''EXCEL'' FROM DUAL UNION ALL SELECT ''Cust.FCST_RPA[P+P]'', '' └ '' || ''RPA'' FROM DUAL UNION ALL SELECT ''Immidiate[Org.]'', ''    └ '' || ''Immidiate[Org.]'' FROM DUAL UNION ALL SELECT ''Planning_Forecast[Org.]'', ''    └ '' || ''Planning_Forecast[Org.]'' FROM DUAL UNION ALL SELECT ''Commercial_Agreement[Org.]'', ''    └ '' || ''Commercial_Agreement[Org.]'' FROM DUAL UNION ALL SELECT ''Firm_Temp[Org.]'', ''    └ '' || ''Firm_Temp[Org.]'' FROM DUAL UNION ALL SELECT ''Manumacturing_Material_Temp[Org.]'', ''    └ '' || ''Manumacturing_Material_Temp[Org.]'' FROM DUAL UNION ALL SELECT ''Material_Temp[Org.]'', ''    └ '' || ''Material_Temp[Org.]'' FROM DUAL UNION ALL SELECT ''Backorder[Org.]'', ''    └ '' || ''Backorder[Org.]'' FROM DUAL UNION ALL SELECT ''Cust.FCST_EXCEL[Org.]'', '' └ '' || ''EXCEL[Org.]'' FROM DUAL UNION ALL SELECT ''Cust.FCST_RPA[Org.]'', '' └ '' || ''RPA[Org.]'' FROM DUAL UNION ALL SELECT ''Cust.FCST_EXCEL'', '' └ '' || ''EXCEL'' FROM DUAL UNION ALL SELECT ''Cust.FCST_RPA'', '' └ '' || ''RPA'' FROM DUAL UNION ALL SELECT ''Ship Plan'', ''Ship Plan'' FROM DUAL UNION ALL SELECT ''CUST_FCST_EDI'', '' └ '' || ''EDI'' FROM DUAL' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'minyonglee1' AS CREATED_BY, TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'admin' AS LAST_UPDATED_BY, TO_DATE('2026-08-26 11:44:41','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) S ON (T.SQL_ID=S.SQL_ID AND T.MDU_DIVS_CD=S.MDU_DIVS_CD)
WHEN MATCHED THEN UPDATE SET T.SQL_NM=S.SQL_NM, T.SQL_DTL_CTN=S.SQL_DTL_CTN, T.USE_YN=S.USE_YN, T.LAST_UPDATED_BY=S.LAST_UPDATED_BY, T.LAST_UPDATE_DATE=S.LAST_UPDATE_DATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE) VALUES (S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, S.CREATED_BY, S.CREATION_DATE, S.LAST_UPDATED_BY, S.LAST_UPDATE_DATE);
