MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T USING (SELECT 'SiteByEndCustomer' AS SQL_ID, 'DM' AS MDU_DIVS_CD, 'SCM Site by End Customer' AS SQL_NM, 'SELECT DISTINCT 	A.DIVISION_ID AS DIVISION_ID, 	A.END_CUSTOMER AS END_CUSTOMER,     A.SCM_SITE_ID AS CODE,     A.SCM_SITE_ID AS NAME FROM SCM_MST_SITE A LEFT JOIN SCM_MST_SITE_ITEM B     ON (@divisionId = ''40'' AND A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID) LEFT JOIN (     SELECT REGEXP_SUBSTR(@endCustomer, ''[^,]+'', 1, LEVEL) AS token     FROM DUAL     CONNECT BY REGEXP_SUBSTR(@endCustomer, ''[^,]+'', 1, LEVEL) IS NOT NULL ) C ON (1=1) WHERE A.SITE_TYPE = ''SALES''   AND A.VALID_YN = ''Y''   AND (         @divisionId IS NULL         OR @divisionId = ''''         OR @divisionId = ''ALL''         OR A.DIVISION_ID IN (             SELECT REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL)             FROM DUAL             CONNECT BY REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) IS NOT NULL         )       )   AND (         @endCustomer IS NULL         OR @endCustomer = ''''         OR @endCustomer = ''ALL''         OR (             @divisionId <> ''40''             AND A.END_CUSTOMER = CASE                 WHEN @endCustomer = ''ALL'' OR @endCustomer = '''' THEN A.END_CUSTOMER                 ELSE C.token             END         )         OR (             @divisionId = ''40''             AND B.PROJECT_CODE = CASE                 WHEN @endCustomer = ''ALL'' OR @endCustomer = '''' THEN B.PROJECT_CODE                 ELSE C.token             END         )       )   AND A.DIVISION_ID IN (         SELECT DISTINCT UNIT_ID         FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M         WHERE USER_ID = @sesUserId           AND UNIT_TP_CD = ''D''     ) ORDER BY A.SCM_SITE_ID ASC' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'SYSTEM' AS CREATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'admin' AS LAST_UPDATED_BY, TO_DATE('2026-07-23 19:42:45','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) S ON (T.SQL_ID=S.SQL_ID AND T.MDU_DIVS_CD=S.MDU_DIVS_CD)
WHEN MATCHED THEN UPDATE SET T.SQL_NM=S.SQL_NM, T.SQL_DTL_CTN=S.SQL_DTL_CTN, T.USE_YN=S.USE_YN, T.LAST_UPDATED_BY=S.LAST_UPDATED_BY, T.LAST_UPDATE_DATE=S.LAST_UPDATE_DATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE) VALUES (S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, S.CREATED_BY, S.CREATION_DATE, S.LAST_UPDATED_BY, S.LAST_UPDATE_DATE);
